#!/bin/sh
# Xcode Cloud (#55): Shoo.xcodeproj is generated by XcodeGen and never committed, so make it here,
# right after the clone, before Xcode Cloud looks for ios/Shoo.xcodeproj.
set -eu

cd "$CI_PRIMARY_REPOSITORY_PATH/ios"

# Signing for the cloud build: the workflow's environment variables stand in for the gitignored
# Config/Local.xcconfig. Team ID, bundle ID and App Group are not secrets; they live in App Store
# Connect, never in the repo (ios/CLAUDE.md).
if [ -n "${SHOO_TEAM_ID:-}" ]; then
  {
    echo "DEVELOPMENT_TEAM = $SHOO_TEAM_ID"
    echo "SHOO_BUNDLE_ID = ${SHOO_BUNDLE_ID:?set SHOO_BUNDLE_ID with SHOO_TEAM_ID}"
    echo "SHOO_APP_GROUP = ${SHOO_APP_GROUP:?set SHOO_APP_GROUP with SHOO_TEAM_ID}"
  } > Config/Local.xcconfig
fi

brew install xcodegen
xcodegen generate
